"""Seeded synthetic patient generation.

All randomness in the simulation lives here. Patients are sampled once, before either
track runs, and the same immutable tuple is handed to both tracks.
"""

from __future__ import annotations

import hashlib
import math
import random

from app.simulation.hospitals import Network
from app.simulation.models import TICK_MINUTES, TICKS_PER_HOUR, Mode, Patient
from app.simulation.scenarios import AcuityMix, Scenario

WARMUP_TICKS = 32  # 8 simulated hours to reach a realistic starting occupancy

# Relative arrival intensity by clock hour (synthetic ED-like shape, mean ~0.92).
DIURNAL_PROFILE: tuple[float, ...] = (
    0.55, 0.48, 0.42, 0.40, 0.40, 0.45, 0.60, 0.80, 1.00, 1.15, 1.25, 1.30,
    1.32, 1.30, 1.28, 1.25, 1.22, 1.20, 1.18, 1.12, 1.05, 0.95, 0.80, 0.65,
)  # fmt: skip

WALK_IN_ACUITY_MIX: AcuityMix = (0.06, 0.44, 0.50)
AMBULANCE_ACUITY_MIX: AcuityMix = (0.28, 0.52, 0.20)
SERVICE_MEAN_MINUTES = {1: 300.0, 2: 200.0, 3: 100.0}
SERVICE_SIGMA = 0.45  # lognormal shape


def derive_seed(*parts: object) -> int:
    """Stable 64-bit seed from arbitrary parts (independent of PYTHONHASHSEED)."""
    digest = hashlib.sha256("|".join(str(p) for p in parts).encode()).digest()
    return int.from_bytes(digest[:8], "big")


def poisson(rng: random.Random, lam: float) -> int:
    if lam <= 0:
        return 0
    limit = math.exp(-lam)
    k, p = 0, 1.0
    while True:
        p *= rng.random()
        if p <= limit:
            return k
        k += 1


def _choose_acuity(rng: random.Random, mix: AcuityMix) -> int:
    r = rng.random() * sum(mix)
    cumulative = 0.0
    for acuity, weight in enumerate(mix, start=1):
        cumulative += weight
        if r < cumulative:
            return acuity
    return 3


def _service_ticks(rng: random.Random, acuity: int, multiplier: float) -> int:
    mean = SERVICE_MEAN_MINUTES[acuity] * multiplier
    mu = math.log(mean) - SERVICE_SIGMA**2 / 2
    minutes = rng.lognormvariate(mu, SERVICE_SIGMA)
    return max(1, round(minutes / TICK_MINUTES))


def expected_arrivals_per_tick(base_per_hour: float, clock_hour: int, multiplier: float) -> float:
    return base_per_hour * DIURNAL_PROFILE[clock_hour] * multiplier / TICKS_PER_HOUR


def generate_patients(
    network: Network,
    scenario: Scenario,
    seed: int,
    warmup_ticks: int = WARMUP_TICKS,
) -> tuple[Patient, ...]:
    """Pre-sample every arrival from tick -warmup_ticks to the end of the horizon."""
    raw: list[tuple[int, int, int, Patient]] = []
    for h_index, hospital in enumerate(network.hospitals):
        rng = random.Random(derive_seed("triagex", seed, scenario.id, hospital.id))
        bursts = [b for b in scenario.bursts if b.hospital_id == hospital.id]
        for tick in range(-warmup_ticks, scenario.horizon_ticks):
            n_in_tick = 0

            def make(mode: Mode, mix: AcuityMix, source: str, tick: int = tick) -> None:
                nonlocal n_in_tick
                acuity = _choose_acuity(rng, mix)
                service = _service_ticks(rng, acuity, scenario.service_multiplier)
                pid = f"{hospital.id}:{tick}:{n_in_tick}"
                raw.append(
                    (tick, h_index, n_in_tick, Patient(0, pid, hospital.id, tick, mode, acuity,
                                                       service, source))
                )
                n_in_tick += 1

            lam = expected_arrivals_per_tick(
                hospital.base_arrivals_per_hour,
                scenario.clock_hour(tick),
                scenario.demand_multiplier(hospital.id, tick),
            )
            amb_frac = min(1.0, max(0.0, hospital.ambulance_fraction
                                    + scenario.ambulance_fraction_delta))
            walk_mix = scenario.walk_in_acuity_mix or WALK_IN_ACUITY_MIX
            for _ in range(poisson(rng, lam)):
                if rng.random() < amb_frac:
                    make(Mode.AMBULANCE, AMBULANCE_ACUITY_MIX, "baseline")
                else:
                    make(Mode.WALK_IN, walk_mix, "baseline")

            for burst in bursts:
                for _ in range(poisson(rng, burst.expected_at(tick))):
                    mode = Mode.AMBULANCE if rng.random() < burst.ambulance_fraction else Mode.WALK_IN
                    make(mode, burst.acuity_mix, "surge")

    raw.sort(key=lambda item: item[:3])
    return tuple(
        Patient(seq, p.id, p.hospital_id, p.arrival_tick, p.mode, p.acuity, p.service_ticks,
                p.source)
        for seq, (*_, p) in enumerate(raw)
    )

"""Human-approved TriageX interventions (Track B only).

An intervention is an input to the simulation, never something the engine decides on
its own. Proposals are generated by the engine; interventions exist only once a human
approves them (and, for staffing, once staff confirm).
"""

from __future__ import annotations

from dataclasses import dataclass

from app.simulation.hospitals import Network
from app.simulation.models import Proposal

STAFF_LEAD_TICKS = 3  # 45 simulated minutes between request and staff on the floor
STAFF_SHIFT_TICKS = 16  # 4-hour surge shift
LEVEL_LOAD_LEAD_TICKS = 1  # 15 minutes to notify EMS dispatch
LEVEL_LOAD_DURATION_TICKS = 16
MAX_CONFIRMED_STAFF = 20


@dataclass(frozen=True, slots=True)
class StaffingIntervention:
    """Confirmed extra staff for one hospital. Effective only after the lead time."""

    id: str
    hospital_id: str
    approved_tick: int  # when the operator approved the outreach request
    confirmed_staff: int  # number of staff who replied IN
    lead_ticks: int = STAFF_LEAD_TICKS
    duration_ticks: int = STAFF_SHIFT_TICKS

    @property
    def effective_tick(self) -> int:
        return self.approved_tick + self.lead_ticks

    @property
    def end_tick(self) -> int:  # exclusive
        return self.effective_tick + self.duration_ticks

    def active(self, tick: int) -> bool:
        return self.confirmed_staff > 0 and self.effective_tick <= tick < self.end_tick


@dataclass(frozen=True, slots=True)
class LevelLoadingIntervention:
    """Redirect lower-acuity inbound ambulances away from a pressured hospital."""

    id: str
    source_hospital_id: str
    approved_tick: int
    max_redirects_per_tick: int = 2
    min_acuity: int = 3  # only the least urgent patients are redirected
    receiver_forecast_limit_pct: float = 80.0
    lead_ticks: int = LEVEL_LOAD_LEAD_TICKS
    duration_ticks: int = LEVEL_LOAD_DURATION_TICKS

    @property
    def hospital_id(self) -> str:
        return self.source_hospital_id

    @property
    def effective_tick(self) -> int:
        return self.approved_tick + self.lead_ticks

    @property
    def end_tick(self) -> int:
        return self.effective_tick + self.duration_ticks

    def active(self, tick: int) -> bool:
        return self.effective_tick <= tick < self.end_tick


Intervention = StaffingIntervention | LevelLoadingIntervention


def validate_interventions(
    interventions: tuple[Intervention, ...], network: Network, horizon_ticks: int
) -> None:
    ids = [iv.id for iv in interventions]
    if len(set(ids)) != len(ids):
        raise ValueError("Intervention ids must be unique")
    for iv in interventions:
        if iv.hospital_id not in network.index:
            raise ValueError(f"Intervention {iv.id}: unknown hospital '{iv.hospital_id}'")
        if not (0 <= iv.approved_tick < horizon_ticks):
            raise ValueError(f"Intervention {iv.id}: approved_tick outside the horizon")
        if iv.lead_ticks < 0 or iv.duration_ticks <= 0:
            raise ValueError(f"Intervention {iv.id}: invalid lead or duration")
        if isinstance(iv, StaffingIntervention):
            if not (0 <= iv.confirmed_staff <= MAX_CONFIRMED_STAFF):
                raise ValueError(f"Intervention {iv.id}: confirmed_staff out of range")
        elif isinstance(iv, LevelLoadingIntervention):
            if iv.max_redirects_per_tick < 0 or iv.min_acuity not in (1, 2, 3):
                raise ValueError(f"Intervention {iv.id}: invalid level-loading limits")
        else:
            raise TypeError(f"Unsupported intervention type: {type(iv).__name__}")


def interventions_from_proposal(
    proposal: Proposal,
    approved_tick: int,
    confirmed_staff: int,
    include_level_loading: bool = True,
) -> tuple[Intervention, ...]:
    """Build the interventions a human approval of `proposal` would create."""
    if approved_tick < proposal.tick:
        raise ValueError("A proposal cannot be approved before it was made")
    result: list[Intervention] = [
        StaffingIntervention(
            id=f"{proposal.id}:staffing",
            hospital_id=proposal.hospital_id,
            approved_tick=approved_tick,
            confirmed_staff=confirmed_staff,
        )
    ]
    if include_level_loading:
        result.append(
            LevelLoadingIntervention(
                id=f"{proposal.id}:level_loading",
                source_hospital_id=proposal.hospital_id,
                approved_tick=approved_tick,
            )
        )
    return tuple(result)

