def series_digest(result):
    h=hashlib.sha256()
    for tick in result.ticks:
        for x in tick:
            h.update(f'{x.tick},{x.hospital_id},{x.status.value},{x.saturation_pct!r},{x.occupied},{x.queue_length},{x.ambulance_queue_length},{x.staff_on_duty},{x.staffed_capacity},{x.mean_current_wait_minutes!r},{x.forecast_saturation_pct!r},{x.diverting:d},{x.diverted_out},{x.transfers_out};'.encode())
    return h.hexdigest()
t=time.perf_counter(); d=series_digest(r); print('series_digest: %.2f ms'%((time.perf_counter()-t)*1000), d[:12])
